//! A smoke test of the TON Firehose: counts what every block holds and keeps
//! running totals in a store, so a run goes through both substreams tiers.
//! The block is read through its lazy view: only the fields counted here are
//! decoded.

// The handlers of substreams::handlers are exported functions that read their
// input behind a pointer of the host, and keep no attribute of ours.
#![allow(clippy::not_unsafe_ptr_arg_deref)]

// Generated by buffa: names and shapes are those of the .proto files, some
// of which the module does not use.
#[allow(clippy::all, dead_code)]
mod pb {
    include!(concat!(env!("OUT_DIR"), "/smoke.v1.mod.rs"));
}

use pb::{BlockStats, Totals};
use substreams::errors::Error;
use substreams::store::{StoreAdd, StoreAddInt64, StoreGet, StoreGetInt64, StoreNew};
use substreams_ton::types::{BlockDataLazyView, BlockLazyView};

#[substreams::handlers::map]
fn map_block_stats(block: &BlockLazyView<'_>) -> Result<BlockStats, Error> {
    let master = block.masterchain_block.get()?.ok_or_else(|| Error::msg("no masterchain block"))?;
    let info = master.info.get()?.ok_or_else(|| Error::msg("no block info"))?;
    let mut stats = BlockStats {
        seqno: info.seq_no,
        gen_utime: info.gen_utime,
        shard_blocks: block.shard_blocks.len() as u32,
        traces: block.traces.len() as u32,
        ..Default::default()
    };
    count(&master, &mut stats)?;
    for data in &block.shard_blocks {
        count(&data?, &mut stats)?;
    }
    Ok(stats)
}

fn count(data: &BlockDataLazyView<'_>, stats: &mut BlockStats) -> Result<(), Error> {
    let Some(extra) = data.extra.get()? else { return Ok(()) };
    for account in &extra.account_blocks {
        let account = account?;
        stats.transactions += account.transactions.len() as u64;
        for tx in &account.transactions {
            stats.out_messages += tx?.outmsg_cnt as u64;
        }
    }
    Ok(())
}

#[substreams::handlers::store]
fn store_totals(stats: BlockStats, store: StoreAddInt64) {
    store.add(0, "blocks", 1);
    store.add(0, "transactions", stats.transactions as i64);
    store.add(0, "traces", stats.traces as i64);
}

// A store cannot be the output of a run: this map reads it.
#[substreams::handlers::map]
fn map_totals(stats: BlockStats, totals: StoreGetInt64) -> Result<Totals, Error> {
    let get = |key: &str| totals.get_last(key).unwrap_or(0);
    Ok(Totals {
        seqno: stats.seqno,
        blocks: get("blocks"),
        transactions: get("transactions"),
        traces: get("traces"),
        ..Default::default()
    })
}
